// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    uint constant MIN_DEPOSIT = 1 ether;

    function setUp() public { c = new Private_Bank(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 0, MIN_DEPOSIT);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();
        // Rule: a deposit with value <= MinDeposit must never credit the actor's balance.
        assertTrue(c.balances(actor) == 0);
    }
}
